#!/usr/bin/env python3
"""Generate lib/verify/intel_anchors.resid from Intel's SGX root.

Usage: tools/attest/gen_intel_anchors.py ROOT.der
(https://certificates.trustedservices.intel.com/Intel_SGX_Provisioning_Certification_RootCA.cer)
"""
import hashlib, sys

der = open(sys.argv[1], "rb").read()
xs = [str(x) for x in der]
rows = ",\n        ".join(", ".join(xs[i:i + 24]) for i in range(0, len(xs), 24))
fp = hashlib.sha384(der).hexdigest()
sys.stdout.write(f'''// GENERATED by tools/attest/gen_intel_anchors.py from Intel's SGX
// Provisioning Certification root; do not edit. verify/intel_anchors.resid
// — the root of every PCK chain a TDX quote carries (PLAN-attestation.md
// §3.1). Rebuild-only.

import "core.resid";
import "tdx.resid";
import "claims.resid";

/// Intel's SGX provisioning certification root CA, as the anchor for TDX quotes.
@anchor(kind = IntelPck(SgxRoot), principal = InGuest, formats = [TdxQuote], source = "https://certificates.trustedservices.intel.com/Intel_SGX_Provisioning_Certification_RootCA.cer", fingerprint = "sha384:{fp}", retrieved = "2026-10-11", reviewed_by = "Larry Dewey", algorithms = [EcdsaP256Sha256], expires = "2049-12-31")
pub Anchor intel_sgx_root() {{ return anchor_der(intel_sgx_root_der()); }}

/// The DER bytes of Intel's SGX provisioning certification root CA.
pub List(Int) intel_sgx_root_der() {{
    return [
        {rows}
    ];
}}

/// Intel's SGX root, for TDX quotes, as a trust set.
@trust(anchors = [intel_sgx_root])
pub Trust intel_roots() {{ return trust_anchors(); }}
''')
